StructuredTextModel.Text:
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			HE_LightControl_Logic                                                                                                                                                                                                                                                                           
//	CREATOR:		Helgevold - William Veim                                                                                                                                                                                                                                                              
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE				SIGN						DESCRIPTION                                                                                                                                                                                     
//	1.0.0				2025-03-03		William Veim			Initial release
//	2.0.0				2025-03-03		William Veim			Rework
//	2.0.1				2025-04-29		Ruben Byman			Added alarm trigger and bug fix state control
//	2.0.2				2025-05-06		Ruben Byman			Changed time of day inputs from SCADA from STRING to 2x INTs and expanded STRING EndTime to format "17:59"
//	2.0.3				2025-09-02		William Veim			Bugfix emergency dimming and condition for start dimming
//	2.1.0				2025-09-02		William Veim			Removed input "Cfg_ControlCabinet"
//	2.1.1				2026-01-15		William Veim			Emergency dim down - Changed min value to zero ("EXT_Engineering.MinGain" was used)
//	2.2.0				2026-01-20		Ruben Byman			Added ramping in manual mode, after entering auto mode and after exiting predefined state
//	2.2.1				2026-02-18		William Veim			Bugfix adding new time - And new condition that new time is lower than 24h before adding
//	3.0.0				2026-05-22		Ruben Byman			Moved to BaseBlocks and changed name to LightControl_Logic to implement wrappers in main library
//
//===============================================================================================================================
//
//		DESCRIPTION:
//		Block for light control based on start time and desired light duration. Option to increase light duration per day. Outputs as analog and digital values.
//
//================================================================================================================================

Time_Current := 	TruncTod(DT_TO_TOD(In:=GetTime()), _SEC);
DayOfWeek:= 		GetDayOfWeek(In:=GetTime());

(*************************************************************************
 *	INITIALISING VARIABELS
 *************************************************************************)

Ext_LightControl.EXT_Alarm.Sts_SupressIfOff_Visible:=TRUE;
Ext_LightControl.EXT_Engineering.EmergencyDimDown_Visible:=Cfg_UPS_Present;
Ext_LightControl.EXT_General.Controlled_FromController:=Cfg_ControllerName;

IF NOT Ext_LightControl.INT_Data.Initialise THEN
	
	//Operator settings
	Ext_LightControl.EXT_Operator.DimDown_Time:=30;
	Ext_LightControl.EXT_Operator.DimUp_Time:=30;
	Ext_LightControl.EXT_Operator.Dim_Time_Overall:=1;
	Ext_LightControl.EXT_Operator.LightDuration_Hour:=12;
	Ext_LightControl.EXT_Operator.LightDuration_Minute:=00;
	Ext_LightControl.EXT_Operator.StartTime_Hour:=07;
	Ext_LightControl.EXT_Operator.StartTime_Minute:=00;
	
	//Engineering settings
	Ext_LightControl.EXT_Engineering.MaxGain:=100;
	Ext_LightControl.EXT_Engineering.MinGain:=0;
	Ext_LightControl.EXT_Engineering.Light_MinGain:=0;
	Ext_LightControl.EXT_Engineering.Light_MaxGain:=254;
	
	//State config
	Ext_LightControl.EXT_Engineering.StateCfg_1.Cfg_Quality:=0; //Configuration fault = Diagnostic
	Ext_LightControl.EXT_Engineering.StateCfg_1.Cfg_Alarm:=TRUE; //Configuration fault = Alarm
	Ext_LightControl.EXT_Engineering.StateCfg_2.Cfg_Quality:=0; //Interlock = Diagnostic
	Ext_LightControl.EXT_Engineering.StateCfg_2.Cfg_Alarm:=TRUE; //Interlock = Alarm
	
	//Alarm settings
	Ext_LightControl.EXT_Alarm.Cfg_SupressDelayOff:=10;
	Ext_LightControl.EXT_Alarm.Cfg_AlarmActiveDelay:=10;
	Ext_LightControl.EXT_Alarm.Cfg_AlarmReturnDelay:=10;
	
	//Init complete
	Ext_LightControl.INT_Data.Initialise:=TRUE;
	
END_IF;

(*************************************************************************
 *	Variable control
 *************************************************************************)
TOF_CPUStartup(In:=P_First_Run, PT:= T#5s);

// Delayed after CPU startup
IF NOT TOF_CPUStartup.Q THEN

	Wrk_VoltageState:=Inp_Voltage_State;
	
END_IF;

Ext_LightControl.EXT_Engineering.MinGain:=LIMIT(MN:=REAL#0, 
																					In:=Ext_LightControl.EXT_Engineering.MinGain, 
																					MX:=REAL#100);

Ext_LightControl.EXT_Engineering.MaxGain:=LIMIT(MN:=REAL#0, 
																					In:=Ext_LightControl.EXT_Engineering.MaxGain, 
																					MX:=REAL#100);



IF DayOfWeek <> DayOfWeek_Sample THEN
	Wrk_IncreaseTodayDone:=FALSE;
	DayOfWeek_Sample:=DayOfWeek;
END_IF;

(*************************************************************************
 *	Parameter adjust active day check
 *************************************************************************)

CASE DayOfWeek OF
		
			_MON:
			Wrk_ParameterAdjustActive := Ext_LightControl.EXT_Engineering.ParameterAdjust_ActiveDays[0];//Active if pos 0 in array configured (TRUE)
			
			_TUE:
			Wrk_ParameterAdjustActive := Ext_LightControl.EXT_Engineering.ParameterAdjust_ActiveDays[1]; //Active if pos 1 in array configured (TRUE)
			
			_WED:
			Wrk_ParameterAdjustActive := Ext_LightControl.EXT_Engineering.ParameterAdjust_ActiveDays[2]; //Active if pos 2 in array configured (TRUE)
			
			_THU:
			Wrk_ParameterAdjustActive := Ext_LightControl.EXT_Engineering.ParameterAdjust_ActiveDays[3]; //Active if pos 3 in array configured (TRUE)
			
			_FRI:
			Wrk_ParameterAdjustActive := Ext_LightControl.EXT_Engineering.ParameterAdjust_ActiveDays[4]; //Active if pos 4 in array configured (TRUE)
			
			_SAT:
			Wrk_ParameterAdjustActive := Ext_LightControl.EXT_Engineering.ParameterAdjust_ActiveDays[5]; //Active if pos 5 in array configured (TRUE)
			
			_SUN:
			Wrk_ParameterAdjustActive := Ext_LightControl.EXT_Engineering.ParameterAdjust_ActiveDays[6]; //Active if pos 6 in array configured (TRUE)
			
END_CASE;

(*************************************************************************
 *	Criteria for starting up and down dimming
 *************************************************************************)
 
  //EMERGENCY DIM DOWN CONTROL
  //----------------------------------------
  
 TON_EmergencyDim(In:=Cfg_UPS_Present AND NOT Wrk_VoltageState, PT:=SecToTime(Ext_LightControl.EXT_Engineering.EmergencyDimDown_Delay*60)); 
 RE_EmergencyDimDown(Clk:=TON_EmergencyDim.Q);
 
 //Sets light control to emergency dimming step after delay
 IF RE_EmergencyDimDown.Q THEN
	 IF Ext_LightControl.EXT_Engineering.EmergencyDimDown_ActiveAuto THEN
		 LightControl_Step := EmergencyDimDown;
	 END_IF;
	 IF Ext_LightControl.EXT_Engineering.EmergencyDimDown_ActiveManual THEN
		 Wrk_ManualMode_State:=1;
	 END_IF;
 END_IF;
 
 //VOLTAGE FAULT -> STANDBY (UPS not present)
 //----------------------------------------------------
 
IF NOT Wrk_VoltageState AND NOT Cfg_UPS_Present THEN
	
	LightControl_Step := VoltageFault_Standby;
	Wrk_ManualMode_State:=0;
	
END_IF;
 
  //CALCULATIONS FOR AUTO CONTROL
 //----------------------------------------------------
 
//If the light duration is shorter than the total dimming time - the light duration is adjusted
IF HE_INT2Minute(Hour:=Ext_LightControl.EXT_Operator.LightDuration_Hour, Minute:=Ext_LightControl.EXT_Operator.LightDuration_Minute) < (Ext_LightControl.EXT_Operator.DimUp_Time+Ext_LightControl.EXT_Operator.DimDown_Time) THEN
	Wrk_TotalDimmingTime := HE_Sec2Str((Ext_LightControl.EXT_Operator.DimUp_Time+Ext_LightControl.EXT_Operator.DimDown_Time)*60);
	Ext_LightControl.EXT_Operator.LightDuration_Hour := STRING_TO_INT(LEFT(In:=Wrk_TotalDimmingTime, L:=2));
	Ext_LightControl.EXT_Operator.LightDuration_Minute := STRING_TO_INT(RIGHT(In:=Wrk_TotalDimmingTime, L:=2));
END_IF;

Ext_LightControl.EXT_Operator.EndTime := LEFT(TodToString(Time_End),5);


Time_DimUp 		:= HE_INT2TOD(Hour:=Ext_LightControl.EXT_Operator.StartTime_Hour, Minute:=Ext_LightControl.EXT_Operator.StartTime_Minute);
Time_End 			:= ADD_TOD_TIME(Time_DimUp, HE_INT2TIME(Hour:=Ext_LightControl.EXT_Operator.LightDuration_Hour, Minute:=Ext_LightControl.EXT_Operator.LightDuration_Minute));
Time_DimDown 	:= SUB_TOD_TIME(Time_End, SecToTime(Ext_LightControl.EXT_Operator.DimDown_Time*60));

 //Timer for stepwise up-dimming
TON_Dim_Auto(PT:=Time_DimPulse_Auto);
TON_Dim_Manual(PT:=Time_DimPulse_Manual);

RE_Standby(Clk:=LightControl_Step= Standby);

//Checks if the time for dimming down is before midnight
IF Time_DimUp < Time_DimDown THEN
	//Checks if it is outside the light time
	Within_Light_Time:= Time_Current >= Time_DimUp AND Time_Current < Time_DimDown;
	
// Time for dimming down is after midnight
ELSE
	//Checks if it is outside the light time
	Within_Light_Time:= Time_Current >= Time_DimUp OR Time_Current < Time_DimDown;
END_IF;

(*************************************************************************
 *	LIGHT CONTROL/MANAGMENT
 
 *NB! Light control (dim up and down) is running independently
 *of light control mode.
 *************************************************************************)

CASE LightControl_Step OF
	
	Standby:
		
		//Dims up if within light time
		IF Within_Light_Time AND 
			((NOT Cfg_UPS_Present AND Wrk_VoltageState) //UPS not in use and voltage OK		
			OR (Cfg_UPS_Present)) THEN //UPS In use and not emergency dim down

			LightControl_Step := DimUp;
			
			END_IF;
		
		IF RE_Standby.Q AND Wrk_ParameterAdjustActive AND NOT Wrk_IncreaseTodayDone THEN
			
			//Adds the desired increase in light duration
			IF ((Ext_LightControl.EXT_Operator.LightDuration_Hour * 60) +Ext_LightControl.EXT_Operator.LightDuration_Minute + Ext_LightControl.EXT_Engineering.MinuteIncrease_PerDay) < 1440 THEN //Only if new light duration is lower than 24h
				Wrk_NewDuration := HE_INTAdd(Inp_Hour:=Ext_LightControl.EXT_Operator.LightDuration_Hour, Inp_Minute:=Ext_LightControl.EXT_Operator.LightDuration_Minute, Inp_MinuteAdd:=Ext_LightControl.EXT_Engineering.MinuteIncrease_PerDay);
				Ext_LightControl.EXT_Operator.LightDuration_Hour := STRING_TO_INT(LEFT(In:=Wrk_NewDuration, L:=2));
				Ext_LightControl.EXT_Operator.LightDuration_Minute := STRING_TO_INT(RIGHT(In:=Wrk_NewDuration, L:=2));
			END_IF;
			//Increases maximum output
			Ext_LightControl.EXT_Engineering.MaxGain := Ext_LightControl.EXT_Engineering.MaxGain+Ext_LightControl.EXT_Engineering.MaxGainIncrease_PerDay;
			
			//Reduces minimum output
			Ext_LightControl.EXT_Engineering.MinGain := Ext_LightControl.EXT_Engineering.MinGain - Ext_LightControl.EXT_Engineering.MinGainDecrease_PerDay;
			
			//Ensure that increase is only done once a day
			Wrk_IncreaseTodayDone:=TRUE;
			
		END_IF;

	DimUp:

		// Calculates the required time between each step of up-dimming
		Time_DimPulse_Auto := NanoSecToTime((Ext_LightControl.EXT_Operator.DimUp_Time* (100/( REAL_TO_INT(Ext_LightControl.EXT_Engineering.MaxGain-Ext_LightControl.EXT_Engineering.MinGain)))*60)*10**6);
			
		// When the timer has run, increments output (+0.01) and resets the timer
		IF TON_Dim_Auto.Q AND Wrk_Gain_Auto <  Ext_LightControl.EXT_Engineering.MaxGain THEN
			Wrk_Gain_Auto:=Wrk_Gain_Auto+ 0.1;
			TON_Dim_Auto.In := FALSE;
		ELSE
			TON_Dim_Auto.In := TRUE;
		END_IF;
		
		//When the output has reached the set value, up-dimming stops
		IF Wrk_Gain_Auto >= Ext_LightControl.EXT_Engineering.MaxGain THEN
			LightControl_Step := FullBrightness;
			Wrk_Gain_Auto := Ext_LightControl.EXT_Engineering.MaxGain;
		END_IF;
		
	FullBrightness:

		//Dims down outside light time, except for 24-hour light time
		IF NOT Within_Light_Time AND (HE_INT2TIME(Hour:=Ext_LightControl.EXT_Operator.LightDuration_Hour, Minute:=Ext_LightControl.EXT_Operator.LightDuration_Minute) <> TIME#24h) THEN
			LightControl_Step := DimDown;
		END_IF;
		
	DimDown:

		//Calculates the required time between each step of down-dimming
		Time_DimPulse_Auto := NanoSecToTime((Ext_LightControl.EXT_Operator.DimDown_Time * (100/(REAL_TO_INT(Ext_LightControl.EXT_Engineering.MaxGain-Ext_LightControl.EXT_Engineering.MinGain)))*60)*10**6);
			
		//When the timer has run, decrements output (-0.01) and resets the timer
		IF TON_Dim_Auto.Q AND Wrk_Gain_Auto > Ext_LightControl.EXT_Engineering.MinGain THEN
			Wrk_Gain_Auto := Wrk_Gain_Auto- 0.1;
			TON_Dim_Auto.In := FALSE;
		ELSE
			TON_Dim_Auto.In := TRUE;
		END_IF;
		
		//When the output reaches zero, down-dimming stops and updates variables
		IF Wrk_Gain_Auto <= Ext_LightControl.EXT_Engineering.MinGain THEN
			LightControl_Step := Standby;
			Wrk_Gain_Auto := 0;
		END_IF;
		
	EmergencyDimDown:
	
		//Calculates the required time between each step of down-dimming
		Time_DimPulse_Auto := NanoSecToTime((Ext_LightControl.EXT_Engineering.EmergencyDimDown_DimTime * (100/(REAL_TO_INT(Ext_LightControl.EXT_Engineering.MaxGain-Ext_LightControl.EXT_Engineering.MinGain)))*60)*10**6);
		
		//When the timer has run, decrements output (-0.01) and resets the timer
		IF Ext_LightControl.EXT_Operator.Mode = 1 AND Ext_LightControl.EXT_Engineering.EmergencyDimDown_ActiveManual AND Wrk_Gain_Manual > 0 THEN //Ensure no sudden change in output if changing between modes 
			Wrk_Gain_Auto := Wrk_Gain_Manual;
			
		ELSIF TON_Dim_Auto.Q AND Wrk_Gain_Auto > 0 THEN //Decrement output
			Wrk_Gain_Auto := Wrk_Gain_Auto- 0.1;
			TON_Dim_Auto.In := FALSE;
			
		ELSIF Wrk_Gain_Auto <= 0 THEN //Decrement reach zero -> Emergency dimming donw
			EmergencyDimDown_Done_Auto:=TRUE;
			Wrk_Gain_Auto := 0;
			
		ELSE //Restart timer
			TON_Dim_Auto.In := TRUE;
		END_IF;
		
		IF Wrk_VoltageState AND Ext_LightControl.EXT_Engineering.EmergencyDimDown_RestartLight THEN //Voltage return and light set to resume (No need to wait until emergency dim done)
			EmergencyDimDown_Done_Auto := FALSE;
			LightControl_Step := Standby;
			
		ELSIF Wrk_VoltageState AND NOT Ext_LightControl.EXT_Engineering.EmergencyDimDown_RestartLight AND NOT Within_Light_Time AND EmergencyDimDown_Done_Auto THEN //Voltage return and light set to keep off (wait until dim down done, and not whitin light time -> Standby mode)
			EmergencyDimDown_Done_Auto := FALSE;
			LightControl_Step := Standby;
		END_IF;
		
	VoltageFault_Standby:
		
		Wrk_Gain_Auto := 0;
		
		IF Wrk_VoltageState AND Ext_LightControl.EXT_Engineering.EmergencyDimDown_RestartLight THEN //Voltage return and light set to resume
			LightControl_Step := Standby;
			
		ELSIF Wrk_VoltageState AND NOT Ext_LightControl.EXT_Engineering.EmergencyDimDown_RestartLight AND NOT Within_Light_Time THEN //Voltage return and light set to keep off (wait until dim down done, and not whitin light time -> Standby mode)
			LightControl_Step := Standby;
		END_IF;
		
		
			
END_CASE;	

(*************************************************************************
 *	MANUAL MODE STATE CONTROL
 
 *NB! Outside mode case, because emergency dim down need to run
 *independent of actual mode
 *************************************************************************)
 
 CASE Wrk_ManualMode_State OF
	 
	 0: //Voltage fault and UPS not present
	 
	 	Wrk_Gain_Manual :=0;
		
		IF NOT Ext_LightControl.EXT_Engineering.EmergencyDimDown_RestartLight AND NOT Wrk_VoltageState THEN
			Ext_LightControl.EXT_Operator.Manual_Output := 0;
		END_IF;
		
		//Resume to normal operation (change output needed to restart)
		IF Ext_LightControl.EXT_Operator.Manual_Output > 0 AND Wrk_VoltageState THEN
			Wrk_ManualMode_State:=2; 
		END_IF;
		
	 1: //Voltage fault and UPS present - Emergency dim down
			
			Time_DimPulse_Manual := NanoSecToTime((Ext_LightControl.EXT_Engineering.EmergencyDimDown_DimTime * (100/REAL_TO_INT(Ext_LightControl.EXT_Engineering.MaxGain))*60)*10**6);
			
			IF Ext_LightControl.EXT_Operator.Mode = 2 AND Ext_LightControl.EXT_Engineering.EmergencyDimDown_ActiveAuto AND Wrk_Gain_Auto > 0 THEN
				Wrk_Gain_Manual := Wrk_Gain_Auto;
			ELSIF TON_Dim_Manual.Q AND Wrk_Gain_Manual > 0 AND NOT EmergencyDimDown_Done_Manual THEN
				Wrk_Gain_Manual := Wrk_Gain_Manual- 0.1;
				TON_Dim_Manual.In := FALSE;
			ELSE
				TON_Dim_Manual.In := TRUE;
			END_IF;
				
			IF Wrk_Gain_Manual <= 0 THEN
				Wrk_Gain_Manual:=0;
				EmergencyDimDown_Done_Manual :=TRUE;
			END_IF;
			
			//Return from emergency dimming
			IF Wrk_VoltageState THEN
				
				IF NOT Ext_LightControl.EXT_Engineering.EmergencyDimDown_RestartLight THEN
					IF EmergencyDimDown_Done_Manual THEN
						Ext_LightControl.EXT_Operator.Manual_Output := 0;
						EmergencyDimDown_Done_Manual :=FALSE;
						Wrk_ManualMode_State:=2; 
					END_IF;
					
				ELSE 
						EmergencyDimDown_Done_Manual :=FALSE;
						Wrk_ManualMode_State:=2; 
				END_IF;
			END_IF;
				
	 2: //Normal operation
	 	Wrk_Gain_Manual:= Ext_LightControl.EXT_Operator.Manual_Output;
		
 END_CASE;

(*************************************************************************
 *	Retrieves output based on mode
 *************************************************************************)	
 
CASE Ext_LightControl.EXT_Operator.Mode OF
	
    0://Off
			Wrk_ModeOutput := 0;
			
	1://Man			
			Wrk_ModeOutput := Wrk_Gain_Manual;
			
	2://Auto
			Wrk_ModeOutput := Wrk_Gain_Auto;
			
END_CASE;

(*************************************************************************
 *	OVERALL DIMMING OF OUTPUT
 
 *NB! This function is to ensure that no sudden change in output
 * is possible (switching between modes etc..)
 *************************************************************************)

TOF_RampingActive(In:=Wrk_Output < Wrk_OutputSample - 1 OR Wrk_Output > Wrk_OutputSample +1, PT:=SecToTime((Ext_LightControl.EXT_Operator.Dim_Time_Overall*60)));

Wrk_OutputSample:= Wrk_Output;

FB_RampGain(ENS:=TRUE, 
				Inp_RampStart:= TOF_RampingActive.Q AND NOT (NOT Wrk_VoltageState AND NOT Cfg_UPS_Present),	//Ramping active if TOF active and not voltage failure without UPS
				Inp_Value:=Wrk_Output, 
				Cfg_StrokeTime:=SecToTime(In:=(Ext_LightControl.EXT_Operator.Dim_Time_Overall*60)), 
				Cfg_Output_X0:=0,
				Cfg_Output_X1:=Ext_LightControl.EXT_Engineering.MaxGain, 
				Cfg_Resolution:=TRUE, 
				Out_Output=>Ext_LightControl.EXT_Operator.Actual_Output);
		
(*************************************************************************
 *	STATE CONTROL
 *************************************************************************)

//FAULT CONTROL
//---------------------------
Wrk_Interlock:=Inp_Interlock;
Wrk_ConfigFault:=Ext_LightControl.EXT_Engineering.MinGain=Ext_LightControl.EXT_Engineering.MaxGain 
							OR Ext_LightControl.EXT_Operator.DimDown_Time = 0 
							OR Ext_LightControl.EXT_Operator.DimUp_Time = 0;

//Resetter variabler før løkke
Ext_LightControl.EXT_General.Sts_Quality :=  6; //Good
Wrk_ActionState:=	0;

//STATE 1 - Config fault
HE_StateControl(EXT_StateData:=Ext_LightControl.EXT_Engineering.StateCfg_1, 
							Inp_Visibility:=TRUE, 
							Inp_State:=Wrk_ConfigFault, 
							Inp_Desc:='Configuration fault',
							Sts_Quality:=Ext_LightControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[0].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[0].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[0].Alm_Priority);
				
//STATE 2 - Interlock
HE_StateControl(EXT_StateData:=Ext_LightControl.EXT_Engineering.StateCfg_2, 
							Inp_Visibility:=Cfg_Interlock_InUse, 
							Inp_State:=Wrk_Interlock, 
							Inp_Desc:='Interlock', 
							Sts_Quality:=Ext_LightControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[1].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[1].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[1].Alm_Priority);

//STATE 3 - According to input
HE_StateControl(EXT_StateData:=Ext_LightControl.EXT_Engineering.StateCfg_3, 
							Inp_Visibility:=Cfg_State3_InUse, 
							Inp_State:=Inp_State3_State, 
							Inp_Desc:=Inp_State3_Desc, 
							Sts_Quality:=Ext_LightControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[2].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[2].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[2].Alm_Priority);

//STATE 4 - According to input
HE_StateControl(EXT_StateData:=Ext_LightControl.EXT_Engineering.StateCfg_4, 
							Inp_Visibility:=Cfg_State4_InUse, 
							Inp_State:=Inp_State4_State, 
							Inp_Desc:=Inp_State4_Desc, 
							Sts_Quality:=Ext_LightControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[3].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[3].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[3].Alm_Priority);

//STATE 5 - According to input
HE_StateControl(EXT_StateData:=Ext_LightControl.EXT_Engineering.StateCfg_5, 
							Inp_Visibility:=Cfg_State5_InUse, 
							Inp_State:=Inp_State5_State, 
							Inp_Desc:=Inp_State5_Desc, 
							Sts_Quality:=Ext_LightControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[4].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[4].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[4].Alm_Priority);

//In case of power loss, the output is set to zero, or emergency dim down is used
IF (Ext_LightControl.EXT_Operator.Mode=1 AND Wrk_ManualMode_State<2) 
	OR (Ext_LightControl.EXT_Operator.Mode=2 AND LightControl_Step=EmergencyDimDown) THEN
	Wrk_ActionState:=0;
END_IF;

CASE Wrk_ActionState OF
	
	0://Use value
	Wrk_Output := Wrk_ModeOutput;
	
	1://Hold value
	Wrk_Output := Wrk_Output;
	
	2://Pre defined output
	Wrk_Output :=Ext_LightControl.EXT_Engineering.StateCfg_PreDefinedOutput;
	
	3://OFF
	Wrk_Output :=0;
	
END_CASE;

(*************************************************************************
 *	ALARM CONTROL
 *************************************************************************)

//Supress if off mode
IF Ext_LightControl.EXT_Alarm.Sts_SupressIfOff_Visible AND Ext_LightControl.EXT_Alarm.Cfg_SupressIfOff AND Ext_LightControl.EXT_Operator.Mode = 0 THEN
	FB_AlarmLogic.Inp_AlarmSupress:=TRUE;
	FB_AlarmLogic.Inp_AlmSuppressDesc:= 'Off mode';
//Supress from FB input
ELSIF Inp_AlmSuppress THEN
	FB_AlarmLogic.Inp_AlarmSupress:=TRUE;
	FB_AlarmLogic.Inp_AlmSuppressDesc:= Inp_AlmSuppressDesc;
ELSE
	FB_AlarmLogic.Inp_AlarmSupress:=FALSE;
	FB_AlarmLogic.Inp_AlmSuppressDesc:= '';
END_IF;

(*************************************************************************
 *	EXCECUTING ALARM BLOCK
 *************************************************************************)
 
 FB_AlarmLogic(ENS:=TRUE, 
								 Ext_Alarm:=Ext_LightControl.EXT_Alarm, 
								 Int_Alarm:=Int_Alarm, 
								 Inp_AlarmData:=Wrk_AlarmData,
								 Inp_LocationData:=Ext_LightControl.EXT_General.LocationIndex,
								 Inp_Connected_Cabinet:='', 
								 Inp_Connected_Controller:=Cfg_ControllerName, 
								 Inp_Process_TAG:='',
								 Inp_Process_Value:= '',
								 Inp_Process_Desc:=Ext_LightControl.EXT_General.Process_Desc,
								 Out_AlarmToken=>Wrk_AlarmToken, 
								 Out_AlarmTriggered=>Wrk_AlarmTriggered);

(*************************************************************************
 *	GENERATE STATUS STRING
 *************************************************************************)
 
 CASE Ext_LightControl.EXT_Operator.Mode OF 
	 
	 0: //OFF MODE
	 Wrk_StateString := 'Light set to OFF';

	1://MANUAL MODE
		IF Wrk_ManualMode_State = 0 THEN
			Wrk_StateString := 'Lights off - voltage state fault';
		ELSIF Wrk_ManualMode_State = 1 AND NOT EmergencyDimDown_Done_Manual THEN
			Wrk_StateString := 'Light manual mode - Emergency dim down';
		ELSIF Wrk_ManualMode_State = 1 AND NOT EmergencyDimDown_Done_Manual THEN
			Wrk_StateString := 'Light manual mode - Emergency dim down done';
		ELSE	
			Wrk_StateString := 'Light set to manual output';
		END_IF;

	2://AUTO MODE
	
		IF LightControl_Step = DimUp THEN
			Wrk_StateString := 'Light auto mode - Dimming up';
		ELSIF LightControl_Step = DimDown THEN
			Wrk_StateString := 'Light auto mode - Dimming dowm';
		ELSIF LightControl_Step = FullBrightness THEN
			Wrk_StateString := 'Light auto mode - Full brightness';
		ELSIF LightControl_Step = VoltageFault_Standby THEN
			Wrk_StateString := 'Light auto mode - Waiting for next light period';
		ELSIF LightControl_Step = Standby THEN
			Wrk_StateString := 'Light auto mode - Standby';
		END_IF;

		IF NOT Wrk_VoltageState AND NOT Cfg_UPS_Present THEN
			Wrk_StateString := 'Light standby - voltage state fault';
		ELSIF LightControl_Step = EmergencyDimDown AND NOT EmergencyDimDown_Done_Auto THEN
			Wrk_StateString := 'Light auto mode - Emergency dim down';
		ELSIF LightControl_Step = EmergencyDimDown AND EmergencyDimDown_Done_Auto THEN
			Wrk_StateString := 'Light auto mode - Emergency dim down done';
		END_IF;
		
 END_CASE;
								
(*************************************************************************
 *	STATISTIC DATA
 *************************************************************************)
 FB_Statistic(Inp_Feedback:=Ext_LightControl.EXT_Operator.Actual_Output>0, 
					 Inp_Reset_Total:=Ext_LightControl.EXT_Statistics.Reset_OnTime, 
					 Inp_Reset_Service:=Wrk_Dummy);
 
 Ext_LightControl.EXT_Statistics.ResetDate_OnTime:= 	FB_Statistic.Out_ResetDate_Total;
 Ext_LightControl.EXT_Statistics.Light_OnTime:= 		 	LINT_TO_UDINT(TimeToSec(FB_Statistic.Out_RunTime_Total)/3600);	
 Ext_LightControl.EXT_Statistics.NumberOfStarts:=			ULINT_TO_UDINT(FB_Statistic.Out_NumOfStarts);
 
(*************************************************************************
 *	UPDATE OUTPUT
 *************************************************************************)			
 
//BLOCK OUTPUT
Sts_Alarm :=  	Wrk_AlarmTriggered;
Sts_LightStarted := 			Ext_LightControl.EXT_Operator.Actual_Output > 0;
Sts_LightMax := 				Ext_LightControl.EXT_Operator.Actual_Output = Ext_LightControl.EXT_Engineering.MaxGain;
Out_Output :=					Ext_LightControl.EXT_Operator.Actual_Output;

IF Ext_LightControl.EXT_Operator.Actual_Output > 0 THEN
	Out_ByteOutput := REAL_TO_BYTE(ScaleTrans(SclIn:=Ext_LightControl.EXT_Operator.Actual_Output, 
				X0:=0.0, 
				Y0:=Ext_LightControl.EXT_Engineering.Light_MinGain, 
				X1:=100.0, 
				Y1:=Ext_LightControl.EXT_Engineering.Light_MaxGain));
ELSE
	Out_ByteOutput:=0;
END_IF;

//STRUCTURE
Ext_LightControl.EXT_Engineering.Light_MinGain:= LIMIT(MN:=INT#0, In:=Ext_LightControl.EXT_Engineering.Light_MinGain, MX:=INT#254);
Ext_LightControl.EXT_Engineering.Light_MaxGain:= LIMIT(MN:=INT#0, In:=Ext_LightControl.EXT_Engineering.Light_MaxGain, MX:=INT#254);
Ext_LightControl.EXT_General.StateDesc:=	 			Wrk_StateString;
Ext_LightControl.EXT_Operator.Auto_Output:=		Wrk_Gain_Auto;
Ext_LightControl.INT_Data.DimDown_Started := 	LightControl_Step = DimDown;
Ext_LightControl.INT_Data.DimUp_Started := 		LightControl_Step = DimUp;
Ext_LightControl.INT_Data.LightMax := 					Sts_LightMax;
